package com.zheng.algorithm.leetcode.medium;

import com.zheng.algorithm.leetcode.TreeNode;

/**
 * 104. 二叉树的最大深度
 *
 * @author zheng
 * @date 2022/1/19 10:32
 */
public class LeetCode104 {

    public static void main(String[] args) {
        TreeNode root = TreeNode.buildTree(new Integer[]{3, 9, 20, null, null, 15, 7});
        System.out.println(new LeetCode104().maxDepth(root));
    }

    public int maxDepth(TreeNode root) {
        if (root == null) {
            return 0;
        }
        return Math.max(maxDepth(root.left), maxDepth(root.right)) + 1;
    }
}

